//! Every class from the Django project-index corpus with its reduced input.
use anyhow::{Context, Result, ensure};
use serde_json::Value;
use std::{fs, io::BufRead, path::PathBuf};
use ty_plugin_host::{MontyLimits, MontyRunner, PluginEnvironment, PluginHost};
use ty_plugin_protocol::{PluginManifest, PluginRequest, PluginResponse};

#[test]
#[ignore = "requires DJANGO_TY_SOURCE and DJANGO_TY_SCOPED_ORACLE generated by django_scoped_oracle.py"]
fn scoped_class_responses_match_full_index_cpython() -> Result<()> {
    let source = PathBuf::from(std::env::var("DJANGO_TY_SOURCE").context("set DJANGO_TY_SOURCE")?);
    let oracle = PathBuf::from(
        std::env::var("DJANGO_TY_SCOPED_ORACLE").context("set DJANGO_TY_SCOPED_ORACLE")?,
    );
    let package = source.join("python/django_ty");
    let manifest: PluginManifest =
        serde_json::from_slice(&fs::read(package.join("ty-plugin.json"))?)?;
    let id = manifest.id.clone();
    let environment = PluginEnvironment::from_manifests(vec![manifest])?;
    let mut runner = MontyRunner::new(MontyLimits::default())?;
    runner.add_plugin(&id, fs::read(package.join("monty.py"))?)?;
    let host = PluginHost::new(environment, runner);
    let mut count = 0;
    for line in std::io::BufReader::new(fs::File::open(oracle)?).lines() {
        let record: Value = serde_json::from_str(&line?)?;
        let request: PluginRequest = serde_json::from_value(record["request"].clone())?;
        let expected: PluginResponse = serde_json::from_value(record["expected"].clone())?;
        ensure!(
            host.execute(&id, &request)? == expected,
            "scoped class record {count} differs: {}",
            record["request"]["class"]["qualified-name"]
        );
        count += 1;
    }
    ensure!(count >= 2579, "regression corpus shrank: {count}");
    println!("{count} scoped Monty class responses match full-index CPython");
    Ok(())
}
